"""One-off editorial revision: make each first-lesson task add a new move."""
import hashlib
import json
from pathlib import Path

root = Path(__file__).resolve().parents[2]
path = root / 'app/content/courses/foundation.json'
raw = path.read_bytes()
lessons = json.loads(raw)
lesson = next(l for l in lessons if l['id'] == 'path-be')
if lesson['exercises'][0]['revision'] != 1:
    raise SystemExit('This editorial revision has already been applied; refusing to overwrite later work.')
sections = [
('Почему в «Я готов» появляется ещё одно слово?', 'Представь: друг ждёт у двери. Ты говоришь «Я готов» — и можно выходить. Ты не описываешь действие: не «бегу» и не «собираюсь». Ты сообщаешь, в каком ты состоянии.\n\nПо-русски мы говорим «Я готов», но «Я БЫЛ готов» и «Я БУДУ готов». В настоящем времени «есть» обычно пропускаем. В обычной полной английской фразе такого пропуска нет: I am ready. Am — форма глагола be («быть») для I («я»). Глагол не обязательно обозначает действие: «быть готовым» — это состояние. Здесь am связывает человека с этим состоянием и показывает настоящее время. Поэтому в переводе получается просто «Я готов», без неестественного «я есть».\n\nПолезный приём: сначала спроси себя «Я говорю, какой я, или что я делаю?» Для «какой я» собирай I am + состояние. Ready — готов, tired — устал. А в «Я работаю» уже есть действие: I work. Не добавляй am в каждую фразу с I: I am work — ошибка. Работу и другие действия разберём отдельно.\n\nСейчас достаточно одной заготовки: I am … — «Я …». На письме I всегда с большой буквы. Дальше научимся говорить о тебе, о ней и о нас — по одному изменению за раз.'),
('Меняем человека — меняем форму', 'Am, is и are — не три разных действия, а формы одного be («быть»). Примерно как «был, была, были» в русском: смысл тот же, форма подстраивается. По-английски она зависит от того, о ком говорим: I am, you are, he/she/it is, we/they are. Ready и tired при этом не меняются: готов, готова, готовы — всё ready. You значит и «ты», и «вы»; в обоих случаях are.'),
('Состояние или место — связка остаётся', 'Можно сообщить не только «какой я», но и «где я»: I am here — я здесь. Here значит «здесь». Am по-прежнему относится к I. Для вещи можно сказать It is here — это здесь. It заменяет название вещи, о которой уже идёт речь; это не универсальный перевод русского «это».'),
('Отменяем утверждение словом not', 'I am tired — я устал. I am not tired — я не устал. Not отрицает то, что стоит дальше: состояние tired. Поставь not сразу после am, is или are. Не убирай саму связку: I not tired — неполная английская фраза.'),
('Чтобы спросить, вынеси связку вперёд', 'You are ready — сообщаю, что ты готов. Are you ready? — узнаю, готов ли ты. Передвинь are перед you, а ready оставь на месте. Точно так же She is tired → Is she tired? Новых слов не понадобилось: вопрос показывает порядок слов.'),
('Почему слышно I’m, а не I am', 'В обычной американской речи I am часто сливается в I’m: смысл «я…» тот же, произносится короче. Апостроф отмечает пропущенную букву a. You are → you’re, she is → she’s. Сокращение не убирает be: в I’m оно осталось внутри ’m. Можно говорить и писать полную форму — это тоже правильно.')]
lesson['sections'] = [dict(title=t,body=b) for t,b in sections]
lesson['goal'] = 'Описать своё состояние, сказать «не» и спросить, готов ли другой человек.'
lesson['subtitle'] = 'Пойми связку → меняй смысл → скажи о себе'

# Every prompt uses only words/forms already introduced, or taught immediately
# above it. The final two prompts deliberately remove the visible model.
steps = [
('Скажи «Я устал». tired = устал. Начни с I.', ['I am tired.'], 'Собери первую фразу', 'По-русски «Я устал» уже звучит законченно. По-английски tired описывает состояние, а am связывает его с I. Получается три части: кто → am → в каком состоянии. Попробуй заменить ready на tired.', 'I am ready.', 'Я готов.', 'I называет человека, am — форму «быть» в настоящем, tired — состояние. Так ты сообщил об усталости.'),
('Друг говорит о себе: I am ready. Теперь скажи ему «Ты готов».', ['You are ready.'], 'Теперь говорим о тебе', 'You — «ты» или «вы». При смене человека меняется и форма be: I am → you are. Ready оставь как есть. Запоминай пару you are целиком: не нужно решать заново, какую форму взять.', 'You are tired.', 'Ты устал. / Вы устали.', 'Изменился человек: I am → you are. Ready обозначает то же состояние.'),
('Подруга уже собралась. Скажи другу «Она готова». she = она.', ['She is ready.'], 'Говорим о ком-то третьем', 'Если речь об одном человеке, который не я и не ты, пригодятся he — «он» и she — «она». С ними be принимает форму is. Состояние не меняет окончания: ready подходит и для «готов», и для «готова».', 'He is tired.', 'Он устал.', 'She — она; is — форма be с she. По-английски ready не меняется из-за пола человека.'),
('Сообщение о вас обоих: «Мы готовы». we = мы.', ['We are ready.'], 'Теперь нас несколько', 'We — «мы», they — «они». Для этих слов используй are, как для you. Говоришь ли ты о двух людях или о целой команде, we are остаётся одной и той же парой.', 'They are tired.', 'Они устали.', 'We are сообщает о нескольких людях, включая тебя. Ready не получает окончание множественного числа.'),
('В сообщении написано She are tired. Исправь одно неверное слово и напиши фразу целиком.', ['She is tired.'], 'Проверь, к кому относится связка', 'Быстрая проверка: посмотри на слово перед связкой. I → am; he, she, it → is; you, we, they → are. Выбирай по человеку, а не по последнему слову tired или ready.', 'He is ready.', 'Он готов.', 'Ошибка была в паре she are. С she нужна is; tired менять не надо.'),
('Тебя ищут. Напиши «Я здесь». here = здесь.', ['I am here.'], 'Am помогает сказать и где ты', 'I am подходит не только для усталости или готовности. Здесь тоже нет действия: ты сообщаешь своё место. Here — «здесь». Русское «Я здесь» превращается в I am here. В следующих темах узнаем, как назвать более точное место.', 'You are here.', 'Ты здесь.', 'Вместо состояния поставили место here. Связка am всё ещё относится к I.'),
('Телефон нашёлся рядом. Скажи «Он здесь», заменив название телефона на It.', ['It is here.'], 'Для знакомой вещи — it', 'По-русски телефон — «он». По-английски, когда мы говорим о знакомой вещи вроде телефона, обычно используем it. Пара для него — it is. Here уже знакомо: «здесь».', 'It is ready.', 'Оно готово.', 'It заменяет название телефона. С it нужна is, а here сообщает место.'),
('Все ждут подругу, но она ещё собирается. Скажи «Она не готова».', ['She is not ready.', "She isn't ready."], 'Добавь «не», не ломая фразу', 'Not — «не». Сначала собери знакомую пару she is, затем поставь not перед состоянием. Связка остаётся: not меняет смысл на противоположный, но не заменяет is.', 'I am not tired.', 'Я не устал.', 'She is not ready отрицает готовность. Сокращение isn’t означает is not и тоже подходит.'),
('Ты видишь, что подруга зевает. Спроси «Она устала?»', ['Is she tired?'], 'Из сообщения делаем вопрос', 'В утверждении человек идёт первым: she is. Чтобы спросить, поставь связку перед ним: is she? Последнее слово tired остаётся там же. С you точно так же: you are → are you?', 'Are you ready?', 'Ты готов?', 'Is вышло перед she — порядок слов показывает, что это вопрос, а не сообщение.'),
('В переписке сократи I am ready. Напиши ту же фразу с I’m.', ["I'm ready."], 'Пиши так, как часто говорят', 'I’m — короткое I am. В речи два слова сливаются, но связка не исчезает: ’m — остаток am. Это обычная форма в разговоре и переписке, а не особый сленг. Послушай пример.', 'I’m tired.', 'Я устал.', 'I’m ready значит то же, что I am ready. Апостроф заменяет букву a; просто I ready связку теряет.')]
for ex,row in zip(lesson['exercises'],steps):
    prompt,answers,title,body,example,translation,explanation = row
    ex.update(prompt=prompt,answers=answers,context='',hint=body,explanation=explanation,revision=2)
    ex['kind']='rewrite' if ex['id']=='e5' else 'translate'
    ex['guidance']=dict(title=title,body=body,example=example,translation=translation)
for ex in lesson['exercises'][-2:]:
    ex['revision']=2
    ex['context']=''
    ex['hint']='Сначала выбери, о ком говоришь: I am или you are. Для «не» добавь not. В вопросе вынеси связку вперёд.'
lesson['exercises'][-2]['prompt']='Друг спрашивает, как ты. Напиши правду о себе: готов (ready) или устал (tired). Если нужно, добавь «не». Одной фразы достаточно.'
lesson['exercises'][-2]['answers']=['I am ready.', 'I am tired.', 'I am not ready.', 'I am not tired.']
lesson['exercises'][-1]['prompt']='Вы собираетесь выходить. В одном сообщении спроси друга, готов ли он, и скажи, что ты готов. Две короткие фразы; теперь без образца.'
newline='\r\n' if b'\r\n' in raw else '\n'
path.write_bytes((json.dumps(lessons,ensure_ascii=False,indent=2)+'\n').replace('\n',newline).encode())
map_path=root/'app/content/curriculum-mastery-map.json'
text=map_path.read_bytes(); old_map=json.loads(text)
snapshot=next(x for x in old_map['snapshotFiles'] if x['file']=='app/content/courses/foundation.json')
map_path.write_bytes(text.replace(snapshot['sha256'].encode(),hashlib.sha256(path.read_bytes()).hexdigest().encode()))
print('Revised path-be: 12 steps; updated foundation snapshot. Other lessons unchanged.')
